import React, { useState } from 'react';
import axios from 'axios';

function ResumeForm({ setResumeData }) {
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    summary: '',
    experience: '',
    education: '',
    skills: [],
  });
  const [skillInput, setSkillInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSkillInput = (e) => {
    setSkillInput(e.target.value);
  };

  const handleAddSkill = (e) => {
    e.preventDefault();
    const skill = skillInput.trim();
    if (skill && !form.skills.includes(skill)) {
      setForm({ ...form, skills: [...form.skills, skill] });
    }
    setSkillInput('');
  };

  const handleRemoveSkill = (skill) => {
    setForm({ ...form, skills: form.skills.filter(s => s !== skill) });
  };

  const handleAIEnhance = async () => {
    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/ai-resume', form);
      setResumeData(res.data);
      alert('Resume enhanced successfully with AI!');
    } catch (err) {
      console.error('AI enhancement error:', err);
      if (err.response?.status === 500) {
        alert('AI enhancement failed. Please check your OpenAI API key and try again.');
      } else {
        alert('AI enhancement failed. Please check your internet connection and try again.');
      }
    }
    setLoading(false);
  };

  return (
    <div className="resume-form">
      <h2>Enter Your Details</h2>
      <input name="name" placeholder="Full Name" value={form.name} onChange={handleChange} />
      <input name="email" placeholder="Email" value={form.email} onChange={handleChange} />
      <input name="phone" placeholder="Phone" value={form.phone} onChange={handleChange} />
      <textarea name="summary" placeholder="Professional Summary" value={form.summary} onChange={handleChange} />
      <textarea name="experience" placeholder="Work Experience" value={form.experience} onChange={handleChange} />
      <textarea name="education" placeholder="Education" value={form.education} onChange={handleChange} />
      <div className="skills-input-group">
        <input
          type="text"
          placeholder="Add a skill and press Enter"
          value={skillInput}
          onChange={handleSkillInput}
          onKeyDown={e => { if (e.key === 'Enter') handleAddSkill(e); }}
        />
        <button onClick={handleAddSkill} type="button">Add Skill</button>
      </div>
      <div className="skills-chips">
        {form.skills.map((skill, i) => (
          <span className="skill-chip" key={i}>
            {skill}
            <button type="button" onClick={() => handleRemoveSkill(skill)}>&times;</button>
          </span>
        ))}
      </div>
      <button onClick={handleAIEnhance} disabled={loading}>{loading ? 'Enhancing...' : 'Enhance with AI'}</button>
    </div>
  );
}

export default ResumeForm;
